/*
 * GIVE A LEARNER A PATH, IN THE COACH'S ORDER (TASK-L184 §2).
 *
 * A NEW `LearningPath` row every time, never an edit of the old one: the
 * product's replan writes a new row and leaves the old (L86), every read takes
 * the NEWEST path, and the old one stays as the record of what they were doing.
 *
 * Every id is checked against `Concept` and an unknown one is refused BY NAME
 * (the product's L85: the picker's validation, never a silent drop — a dropped
 * concept is a step the coach chose and the learner never sees). A path with
 * no steps, or a concept twice, is refused too.
 *
 * WHAT THEY FINISHED STAYS FINISHED. A step whose concept they have already
 * completed (a `Progress` row with `completedAt`) starts `complete`; the first
 * step that is not is `available`; the rest are `locked`. Positions 0..n-1.
 *
 * THE PATH ROW IS WRITTEN FIRST, THEN ITS STEPS. A crash in between leaves a
 * newest path with some steps missing, which the learner would see until the
 * coach presses Save again — and a second press writes a whole NEW path that
 * supersedes it. The other order would leave steps no path names, which the
 * deletion plan finds only through a path (shared/Rows about), so they would
 * outlive the person. Visible-and-fixable beats invisible-and-undeletable.
 *
 * `rationale` is empty: the coach orders by hand, and a sentence nobody wrote
 * must not appear as though somebody had.
 */
if (Inputs.learnerId !== undefined && Inputs.conceptIds !== undefined) {
  (async () => {
    const R = Noodl.Records;
    const q = (c, where, limit) => R.query(c, where, { limit: limit || 1000, plain: true });
    const refuse = (why) => { Outputs.why = why; Outputs.refuse(); };
    try {
      const learnerId = String(Inputs.learnerId || '').trim();
      const ids = (Array.isArray(Inputs.conceptIds) ? Inputs.conceptIds : []).map((x) => String(x || '').trim()).filter(Boolean);
      if (!learnerId) return refuse('Choose whose path this is.');
      const profiles = await q('LearnerProfile', { learnerId: { equalTo: learnerId } }, 2);
      if (profiles.length !== 1) return refuse('There is no learner with that id.');
      if (!ids.length) return refuse('A path needs at least one step. Add a concept first.');
      const dup = ids.find((x, i) => ids.indexOf(x) !== i);
      if (dup) return refuse('"' + dup + '" is on the path twice. Remove one of them.');
      const concepts = await q('Concept', { conceptId: { containedIn: ids } });
      const known = new Set(concepts.map((c) => c.conceptId));
      const unknown = ids.filter((x) => !known.has(x));
      if (unknown.length) return refuse('This course has no concept called "' + unknown.join('", "') + '". Nothing was saved.');

      const progress = await q('Progress', { learnerId: { equalTo: learnerId } });
      const finished = new Set(progress.filter((p) => p.completedAt).map((p) => p.conceptId));

      const pathId = 'path-' + (typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : String(Date.now()));
      await R.create('LearningPath', { pathId, learnerId, programmeId: null, replanBlockedAt: null });
      let opened = false;
      for (let i = 0; i < ids.length; i++) {
        let status = 'locked';
        if (finished.has(ids[i])) status = 'complete';
        else if (!opened) { status = 'available'; opened = true; }
        await R.create('PathStep', { pathId, position: i, conceptId: ids[i], status, rationale: '', removedAt: null });
      }
      console.log('[dbt:setLearnerPath] learner=' + learnerId + ' path=' + pathId + ' steps=' + ids.length);
      Outputs.pathId = pathId;
      Outputs.steps = ids.length;
      Outputs.done();
    } catch (e) {
      console.error('[dbt:setLearnerPath] stopped: ' + String((e && e.message) || e));
      refuse('That did not finish. Press Save again; it starts a fresh path.');
    }
  })();
}
